window.__TESTDATA__["202508asiav1"] = {"testId": "202508asiav1", "testName": "2025 August Asia v1", "modules": [{"moduleId": "2025-august-asia-v1-rw1", "section": "Reading and Writing", "moduleLabel": "Module 1", "timeLimitMinutes": 32, "questions": [{"id": "re1-q1", "passage": "The unique subak water management system used to irrigate the rice paddy fields of the Indonesian island of Bali has a rich cultural, philosophical, and historical significance dating back to the ninth century. The many elements of subak—terraces, canals, and water temples—are ______: they are joined together into a single cohesive unit.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "difficulty": null, "skill": "Words in Context", "tags": [], "type": "mcq", "choices": ["informal", "optional", "outmoded", "interconnected"], "correctAnswer": 3}, {"id": "re1-q2", "passage": "A team of archaeologists examined 150 spherically shaped limestone rocks called spheroids that date back about 1.4 million years, concluding that early hominins intentionally chipped away at rocks to form these spheroids over time. The fact that their attempt to make the stones as round as possible was ______ suggests that early hominins may have been more cognitively sophisticated than previously thought.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "difficulty": null, "skill": "Words in Context", "tags": [], "type": "mcq", "choices": ["concerning", "comparable", "sympathetic", "deliberate"], "correctAnswer": 3}, {"id": "re1-q3", "passage": "The Egyptian plover—a bird native to Africa—has a symbiotic relationship with the Nile crocodile. While a crocodile rests on land with its mouth open for extended periods of time, the plover eats the food that is stuck in the crocodile’s teeth. This ______ relationship provides a nutritious meal for the bird and removes potentially dangerous bacteria from the crocodile’s mouth.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "difficulty": null, "skill": "Words in Context", "tags": [], "type": "mcq", "choices": ["reciprocal", "interchangeable", "inefficient", "unequal"], "correctAnswer": 0}, {"id": "re1-q4", "passage": "The following text is from Jerome K. Jerome’s 1889 novel {{i}}Three Men in a Boat (To Say Nothing of the Dog){{/i}}. The narrator and two friends are taking a boat down the River Thames in England.{{br}}{{br}}{{quote}}In a boat, I have always noticed that it is the fixed idea of each member of the crew that he is doing everything. Harris’s notion was, that it was he alone who had been working, and that both George and I had been imposing upon him. George, on the other hand, ridiculed the idea of Harris’s having done anything more than eat and sleep, and had a cast-iron opinion that it was he—George himself—who had done all the labour worth speaking of.{{/quote}}", "questionText": "Which choice best describes the main purpose of the text?", "difficulty": null, "skill": "Text Structure and Purpose", "tags": [], "type": "mcq", "choices": ["To give an overview of a particular situation that the narrator finds startling", "To examine how the narrator and his friends each contributed to navigating a challenge", "To present the narrator’s generalization along with supporting examples from a specific situation", "To convey the narrator’s confidence that he understands the role expected of him in a group"], "correctAnswer": 2}, {"id": "re1-q5", "passage": "The following text is adapted from Akwaeke Emezi’s 2019 novel {{i}}Pet{{/i}}. Jam is a teenager who lives with her father, Aloe, and her mother, Bitter, who is a painter.{{br}}{{br}}{{quote}}Bitter finished the painting in the dark morning of a day—it was well past midnight when Jam heard the studio door creak open. She stared into the velvet black of her room and listened to her mother’s footsteps walking in her [mother] and Aloe’s bedroom. There was a weight thrumming through the floorboards in a low song, and that was how Jam knew the painting was done. {{u}}Bitter’s feet were singing the news.{{/u}}{{/quote}}", "questionText": "Which choice best states the function of the underlined sentence in the text as a whole?", "difficulty": null, "skill": "Text Structure and Purpose", "tags": [], "type": "mcq", "choices": ["It describes Aloe’s reaction upon seeing the painting for the first time.", "It indicates that Jam is more interested in music than in art.", "It adds to the idea that Bitter’s footsteps reveal something to Jam.", "It indicates that Bitter always sings when working on a painting."], "correctAnswer": 2}, {"id": "re1-q6", "passage": "In 2016 Ana Filipa Lopes and colleagues published a study concluding that ocean acidification has a strong effect on the behavior of Atherina presbyter, a species of fish. However, Lopes and colleagues’ study relied on a mean sample size of only about 15 fish. In a 2022 review of various scientists’ conclusions about the impacts of ocean acidification on fish behavior, Timothy D. Clark and colleagues caution that relying on such a relatively small sample size can increase the potential for biased analysis. Such analysis, in turn, can contribute to reports of exaggerated effects.", "questionText": "Which choice best states the main purpose of the text?", "difficulty": null, "skill": "Text Structure and Purpose", "tags": [], "type": "mcq", "choices": ["To discuss an aspect of ocean acidification that is frequently overlooked", "To note a potential concern about the findings of a scientific study", "To present a debate between two research teams about a cause of ocean acidification", "To explain how the behavior of a fish species has changed over time"], "correctAnswer": 1}, {"id": "re1-q7", "passage": "Habitat navigation is a skill that helps animals reach food or safety. To test how navigation works in fish, Shachar Givon and colleagues taught goldfish to drive a vehicle—a motorized fish tank with wheels—on land. The vehicle was programmed to move in the same direction that the fish swam in within the tank. In the experiment, the fish were tasked with driving their tank to a pink board. They received a treat when they succeeded, and they often did. Because the fish could move their tank to the board, Givon concludes that their navigational skills aren’t specific to an aquatic environment.", "questionText": "Which choice best states the main idea of the text?", "difficulty": null, "skill": "Central Ideas and Details", "tags": [], "type": "mcq", "choices": ["Fish can navigate only within their natural aquatic environment in order to find food and safety.", "An animal’s navigational skills directly depend on that animal’s particular environment.", "Researchers can train animals to complete many different tasks when they offer the animals treats.", "Research shows that although they live in the water, fish can navigate on land with a little mechanical help."], "correctAnswer": 3}, {"id": "re1-q8", "passage": "Examples of Hoards Found in Ireland and Northern Ireland{{br}}{{table}}Hoard|Year of discovery{{row}}Carrick-on-Suir Hoard|2013{{row}}Ardagh Hoard|1868{{row}}Balline Hoard|1940{{/table}}{{br}}{{br}}Deposits of valuable objects, or hoards, have been unearthed in many different parts of Ireland and Northern Ireland. Some of these hoards were discovered before 2000; for example, ______", "questionText": "Which choice most effectively uses data from the table to complete the statement?", "difficulty": null, "skill": "Command of Evidence (Quantitative)", "tags": [], "type": "mcq", "choices": ["the Ardagh Hoard was discovered in 1868, and the Balline Hoard was discovered in 1940.", "the Ardagh Hoard was one of several hoards discovered in the 1800s.", "the Balline Hoard and the Carrick-on-Suir Hoard were both discovered in the 2000s.", "the Carrick-on-Suir Hoard was discovered in 1940, and the Balline Hoard was discovered in 2013."], "correctAnswer": 0}, {"id": "re1-q9", "passage": "Researcher Helen O’Neill and her team were studying sponges in the family Irciniidae when they discovered that three of the sponges were functioning as microhabitats for banded sand catsharks ({{i}}Atelomycterus fasciatus{{/i}}). Additionally, {{u}}the team found that male and female {{i}}A. fasciatus{{/i}} share the same sponge (the same microhabitat), a{{/u}} behavior not found among Port Jackson sharks ({{i}}Heterodontus portusjacksoni{{/i}}), another seabed-dwelling species.", "questionText": "Which choice best describes data from the graph that support the underlined claim?", "difficulty": null, "skill": "Command of Evidence (Quantitative)", "tags": [], "type": "mcq", "choices": ["Each of the three sponges was inhabited by at least one male A. fasciatus and at least one female A. fasciatus.", "Sponge 1 was inhabited by 17 male A. fasciatus.", "Each of the three sponges was inhabited by at least one male A. fasciatus and at least one undetermined A. fasciatus.", "Sponge 1 was inhabited by 13 female A. fasciatus."], "correctAnswer": 0, "figure": "data:image/png;base64,"}, {"id": "re1-q10", "passage": "Olms are salamanders that live in underwater caves. Scientists once thought that olms stay in their caves all their lives. However, Raoul Manenti and team claim {{u}}that olms regularly come to the surface to perform important activities such as finding food.{{/u}}", "questionText": "Which finding, if true, would most strongly support the underlined claim?", "difficulty": null, "skill": "Command of Evidence (Textual)", "tags": [], "type": "mcq", "choices": ["Researchers discover that earthworms from surface soils are a major part of olms’ diet.", "Researchers learn that olms’ brains differ from other salamanders’ brains.", "Researchers confirm that olms live in only a few cave systems.", "Researchers determine that olms don’t breed often."], "correctAnswer": 0}, {"id": "re1-q11", "passage": "Studies have shown that plants usually have a negative electrical charge, while bees and other pollinators tend to have a positive charge. Because negatively and positively charged objects attract, a team of researchers examined whether this mechanism plays a role in the transmission of pollen between plants and pollinators. The researchers’ experiments showed that positive charges above 200 picocoulombs (pC) could draw pollen grains to a pollinator, so they concluded that both bumblebees and European peacock butterflies can attract pollen.", "questionText": "Which choice best describes data from the graph that support the team’s conclusion?", "difficulty": null, "skill": "Command of Evidence (Quantitative)", "tags": [], "type": "mcq", "choices": ["Both the bumblebees and the European peacock butterflies were found to have maximum charges greater than 200 pC.", "The bumblebees were found to have a maximum charge many times greater than that found for the houseflies.", "The European peacock butterflies were found to have a greater maximum charge than the bumblebees and the houseflies were found to have.", "The houseflies were found to have a maximum charge below 200 pC."], "correctAnswer": 0, "figure": "data:image/png;base64,"}, {"id": "re1-q12", "passage": "Elisabeth Pötzelsberger and colleagues gathered data on 23 non-native tree species grown in Europe. They analyzed reports from Denmark, Finland, and Belgium about the number of these species grown by the timber industries in those countries. The researchers concluded that none of these countries’ timber industries grow all 23 species.", "questionText": "Which choice best describes data from the graph that support Pötzelsberger and colleagues’ conclusion?", "difficulty": null, "skill": "Command of Evidence (Quantitative)", "tags": [], "type": "mcq", "choices": ["There are species other than those reported by Belgium that are important to its timber industry, but they’re native to the country.", "Some of the species that Finland reported are not among the 23 tree species that Pötzelsberger and colleagues were evaluating.", "Denmark, Finland, and Belgium each reported at least 4 of the 23 species.", "Denmark, which reported more of the 23 species than either Finland or Belgium did, reported fewer than 15 of the species."], "correctAnswer": 3, "figure": "data:image/png;base64,"}, {"id": "re1-q13", "passage": "Creeping dogwood ({{i}}Cornus canadensis{{/i}}) plants are native to Alaska, where harsh conditions have historically impeded potential invasive species. As the boreal climate has warmed in recent decades, however, common knotgrass ({{i}}Polygonum aviculare{{/i}}) plants have established themselves in Alaska. It has been suggested that warming-induced delays in the onset of subfreezing temperatures in autumn can benefit invasives more than native species; to evaluate this possibility, biologists Christa Mulder and Katie Spellman tracked C. canadensis and P. aviculare, along with other native and invasive species, over several years, concluding that invasives are advantaged by delays in subfreezing temperature onset in Alaska.", "questionText": "Which finding, if true, would most directly support Mulder and Spellman’s conclusion?", "difficulty": null, "skill": "Command of Evidence (Textual)", "tags": [], "type": "mcq", "choices": ["Although {{i}}C. canadensis{{/i}} and {{i}}P. aviculare{{/i}} both tended to produce leaves later into autumn in years with late subfreezing temperature onset, the extension was much greater for {{i}}P. aviculare{{/i}} than for {{i}}C. canadensis{{/i}}.", "Although {{i}}C. canadensis{{/i}} and {{i}}P. aviculare{{/i}} both tended to produce more leaves overall in years with late subfreezing temperature onset than they did in years with historically typical temperature patterns, the years with late subfreezing temperature onset also had early growing season onset in spring.", "Although {{i}}C. canadensis{{/i}} and {{i}}P. aviculare{{/i}} tended to stop producing leaves at about the same time in years with historically typical temperature patterns, {{i}}P. aviculare{{/i}} stopped producing leaves sooner than {{i}}C. canadensis{{/i}} did in years with late subfreezing temperature onset.", "Although significant interannual variations in subfreezing temperature onset were observed during the study, neither {{i}}P. aviculare{{/i}} nor {{i}}C. canadensis{{/i}} showed any significant interannual variation in the cessation of leaf production."], "correctAnswer": 0}, {"id": "re1-q14", "passage": "Southern Colorado’s Conejos County is among the most rural counties in the United States: the US Census Bureau classified it as 100% rural in 2010. Researchers studying populations of counties like Conejos often struggle to recruit and retain participants. Melissa Valerio and colleagues tested whether a method called snowball sampling could improve recruitment and retention. Working in two rural counties, the researchers identified a small number of people who had the characteristics desired for a proposed study and asked them to recruit additional participants from their social networks. Valerio and colleagues found that participants recruited via snowball sampling showed a much higher retention rate than did people recruited by strangers, suggesting that ______", "questionText": "Which choice most logically completes the text?", "difficulty": null, "skill": "Inferences", "tags": [], "type": "mcq", "choices": ["social networks can become large enough that two people can share a network but nevertheless regard each other as strangers.", "snowball sampling is more likely to improve retention rates among rural participants than among nonrural participants.", "people with relatively small social networks are inherently less likely to be recruited to participate in a study via snowball sampling than are people with relatively large social networks.", "being recruited to participate in a study by someone with whom one is socially connected may impart a feeling of obligation to persist with participation in the study."], "correctAnswer": 3}, {"id": "re1-q15", "passage": "In the periodic table, an element’s atomic number indicates how many protons there are in an atom of the element. For example, a xenon atom ______ 54 protons. Professor Raymond Chang explains this concept in more detail in the textbook Chemistry.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Form, Structure, and Sense", "tags": [], "type": "mcq", "choices": ["had", "has had", "has", "is having"], "correctAnswer": 2}, {"id": "re1-q16", "passage": "Koulsy Lamko, born in 1959, is a playwright from Dadouar, Chad. In recent years more writers from Chad, including Lamko, ______ to reach audiences beyond the African nation’s borders.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Form, Structure, and Sense", "tags": [], "type": "mcq", "choices": ["have begun", "is beginning", "has begun", "begins"], "correctAnswer": 0}, {"id": "re1-q17", "passage": "The Borgia map is a mappa mundi from the fifteenth century. Currently held at the Vatican Library in Vatican City, it is one of over 1,000 such world maps from the European Middle Ages still remaining, with the even older Hereford map from the fourteenth century (now held at Hereford Cathedral in Hereford, England) ______ another one.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Form, Structure, and Sense", "tags": [], "type": "mcq", "choices": ["being", "is", "has been", "was"], "correctAnswer": 0}, {"id": "re1-q18", "passage": "The African baobab ({{i}}Adansonia digitata{{/i}}) known as Panke Baobab, located in Zimbabwe, was one of the oldest known trees in the world, at 2,419 years old. With over two millennia of climate data in its tree ______ single tree like this, claims dendrochronologist Valerie Trouet, can tell the history of the world.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Boundaries", "tags": [], "type": "mcq", "choices": ["rings, a", "rings. A", "rings and a", "rings; a"], "correctAnswer": 0}, {"id": "re1-q19", "passage": "The transit method, a means of indirect planetary discovery, has detected previously unknown exoplanets at vast distances from ______ the super Earth TRAPPIST-1 b; at 352 light-years away, the super Earth Kepler-102 f; and, as of 2023, over 4,000 other exoplanets that are too far away and dim to be observed directly.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Boundaries", "tags": [], "type": "mcq", "choices": ["Earth: at 41 light-years away,", "Earth at 41 light-years away:", "Earth, at 41 light-years away,", "Earth at 41 light-years away,"], "correctAnswer": 0}, {"id": "re1-q20", "passage": "L. Leann Kanda, a researcher and sewing enthusiast, experimented with several techniques in her attempt to replicate the famous pleating of the Fortuny Delphos gown. The specific method, which the fashion ______ developed in the early twentieth century, is considered lost.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Boundaries", "tags": [], "type": "mcq", "choices": ["designers, Henriette Nigrin and Mariano Fortuny y Madrazo", "designers Henriette Nigrin and Mariano Fortuny y Madrazo", "designers Henriette Nigrin and Mariano Fortuny y Madrazo,", "designers, Henriette Nigrin and Mariano Fortuny y Madrazo,"], "correctAnswer": 1}, {"id": "re1-q21", "passage": "While studying jorō spiders, a large species originally from East Asia, University of Georgia researchers wondered if the spiders’ rapid spread throughout the southeastern US was a result of aggressive behavior. ______ they discovered that jorō spiders are gentle giants who react to even minor disturbances by \"freezing\" in place for an hour or more.", "questionText": "Which choice completes the text with the most logical transition?", "difficulty": null, "skill": "Transitions", "tags": [], "type": "mcq", "choices": ["In other words,", "Therefore,", "For example,", "Instead,"], "correctAnswer": 3}, {"id": "re1-q22", "passage": "Some bands choose a name that’s as unique as possible to distinguish themselves from other bands. The electronic rock band Primary, ______ took a different approach. They chose to name themselves after a song by a well-known band, the Cure.", "questionText": "Which choice completes the text with the most logical transition?", "difficulty": null, "skill": "Transitions", "tags": [], "type": "mcq", "choices": ["therefore,", "by contrast,", "for example,", "secondly,"], "correctAnswer": 1}, {"id": "re1-q23", "passage": "Portuguese researcher Isabel C.F.R. Ferreira reports that the caffeic acid in termite mushrooms benefits the mushroom by combating harmful molecules called free radicals. ______ Ferreira suggests that the acid can promote cellular health in humans, who also experience free radical damage.", "questionText": "Which choice completes the text with the most logical transition?", "difficulty": null, "skill": "Transitions", "tags": [], "type": "mcq", "choices": ["Conversely,", "Moreover,", "Rather,", "For example,"], "correctAnswer": 1}, {"id": "re1-q24", "passage": "The Eloi are not real: they are fictional creatures that feature in H.G. Wells’s acclaimed science fiction novella The Time Machine. ______ the Eloi were prime candidates for inclusion in Jorge Luis Borges and Margarita Guerrero’s {{i}}The Book of Imaginary Beings{{/i}}, a compendium of fantastical entities from legend and literature.", "questionText": "Which choice completes the text with the most logical transition?", "difficulty": null, "skill": "Transitions", "tags": [], "type": "mcq", "choices": ["Granted,", "In reality,", "As such,", "For example,"], "correctAnswer": 2}, {"id": "re1-q25", "passage": "While researching a topic, a student has taken the following notes:{{bullets}}A supercontinent is a single landmass made up of most or all of Earth’s continents.{{item}}Over time, continents merge together to form supercontinents, which then break apart.{{item}}This process is believed to take hundreds of millions of years and is known as the supercontinent cycle.{{item}}Ur was a supercontinent that formed about 3.1 billion years ago.{{item}}Pangaea was a supercontinent that formed about 300 million years ago.{{/bullets}}", "questionText": "The student wants to emphasize the order in which the supercontinents were formed. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "difficulty": null, "skill": "Rhetorical Synthesis", "tags": [], "type": "mcq", "choices": ["The supercontinent Pangaea formed long after the supercontinent Ur.", "Forming and breaking apart over hundreds of millions of years, supercontinents are made up of most or all of Earth’s continents.", "Ur and Pangaea were both supercontinents, single landmasses made up of most or all of Earth’s continents.", "Ur formed about 3.1 billion years ago but eventually broke apart."], "correctAnswer": 0}, {"id": "re1-q26", "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Charles Bertram Johnson (1880-1958) was an African American poet.{{item}}Johnson also worked as an educator and minister.{{item}}\"Old Things\" is a poem by Johnson.{{item}}It was published in the March 1923 issue of The Crisis.{{item}}The Crisis is an influential Black literary magazine.{{/bullets}}", "questionText": "The student wants to provide an example of a poem by Johnson. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "difficulty": null, "skill": "Rhetorical Synthesis", "tags": [], "type": "mcq", "choices": ["Johnson was an African American poet, educator, and minister.", "Johnson published poetry in a literary magazine called The Crisis.", "One example of a poem by Johnson is \"Old Things\" (1923).", "The Crisis is an influential Black literary magazine that has published poetry."], "correctAnswer": 2}, {"id": "re1-q27", "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Body positions are an important part of dance.{{item}}In ballroom dance, there is a position called closed facing position.{{item}}It is one of several positions for partner dancing.{{/bullets}}", "questionText": "The student wants to provide an example of a position in ballroom dance. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "difficulty": null, "skill": "Rhetorical Synthesis", "tags": [], "type": "mcq", "choices": ["Closed facing position is an example of a position in ballroom dance.", "In dance, some positions are for partner dancing.", "Body positions are an important part of dance, including ballroom dance.", "Ballroom dance includes several dance positions for partner dancing."], "correctAnswer": 0}]}, {"moduleId": "2025-august-asia-v1-rw2", "section": "Reading and Writing", "moduleLabel": "Module 2", "timeLimitMinutes": 32, "questions": [{"id": "re2-q1", "passage": "Studying advertisements for defunct amusement parks, postcards from vanished tourist destinations, and handbills promoting long-forgotten political candidates may seem like a frivolous pursuit, but ephemeral objects like these are useful as evidence of cultural change: they can ______ shifts in norms, values, and concerns that traditional objects of historical inquiry may not.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "difficulty": null, "skill": "Words in Context", "tags": [], "type": "mcq", "choices": ["dissociate from", "attest to", "collude with", "compensate for"], "correctAnswer": 1}, {"id": "re2-q2", "passage": "In the architectural process called modular construction, a building is manufactured in modules under controlled conditions and then assembled at its intended location. ______ of this approach cite the production of less material waste and the need for fewer personnel.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "difficulty": null, "skill": "Words in Context", "tags": [], "type": "mcq", "choices": ["Safeguards", "Components", "Epitomes", "Proponents"], "correctAnswer": 3}, {"id": "re2-q3", "passage": "Run by researchers in multiple countries, the Study on Global Ageing and Adult Health (SAGE) is an examination of aging that has attempted to track approximately 66,000 people for several years. Long-running studies like this need a lot of participants not merely for statistical robustness but also because of ______: over such a length of time, a substantial number of participants will withdraw or fall out of contact with the researchers.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "difficulty": null, "skill": "Words in Context", "tags": [], "type": "mcq", "choices": ["impartiality", "circumspection", "replicability", "attrition"], "correctAnswer": 3}, {"id": "re2-q4", "passage": "Some ethicists challenge the concept of personal character, claiming that if it were meaningful, situational factors could not, as they clearly can, induce behavior contrary to that character. As Rachana Kamtekar observes, this argument is difficult to reconcile with our lay conception of character: we expect a person of helpful character to be frequently helpful, not ______ helpful.", "questionText": "Which choice completes the text with the most logical and precise word or phrase?", "difficulty": null, "skill": "Words in Context", "tags": [], "type": "mcq", "choices": ["sporadically", "unfailingly", "grudgingly", "self-servingly"], "correctAnswer": 1}, {"id": "re2-q5", "passage": "The Reckoning and Resilience (2022) exhibition at Duke University’s Nasher Museum of Art in Durham, North Carolina, was curated to feature the work of thirty North Carolina artists. The included artists represent a wide variety of artistic disciplines, from painters such as William Paul Thomas to the mixed-media artist Johannes Barfield. In its inclusion of many borrowed works, the exhibition is atypical for the Nasher Museum, which tends to curate its exhibitions around the permanent collection of contemporary art that it owns.", "questionText": "Which choice best describes the overall structure of the text?", "difficulty": null, "skill": "Text Structure and Purpose", "tags": [], "type": "mcq", "choices": ["It discusses the wide range of disciplines represented in an art exhibition, then explains why curators included works in those disciplines.", "It provides an overview of an art exhibition, then explains what makes the exhibition unusual for the institution that organized it.", "It explains how an art exhibition differs from many other exhibitions, then analyzes the significance of that difference.", "It presents the unusual goals curators had for an art exhibition, then evaluates whether the curators achieved those goals."], "correctAnswer": 1}, {"id": "re2-q6", "passage": "The Heege Manuscript (HM) is a collection of booklets of once-unbound paper sheets on which Richard Heege copied various texts at his fifteenth-century home between Derbyshire and Nottinghamshire in England. {{u}}Most other contemporaneous personal manuscripts like the Findern Anthology (FA) consist primarily of pieces for polite society like courtly love poems and other readings favored by elites{{/u}}, whereas the HM has a distinctive emphasis on the popular, including entertainments like nonsense verse, and the practical, with advice about medicine.", "questionText": "Which choice best describes the function of the underlined portion in the text as a whole?", "difficulty": null, "skill": "Text Structure and Purpose", "tags": [], "type": "mcq", "choices": ["To provide context for the text’s suggestion that the HM is an outlier among collections of its time", "To suggest that the FA is a poor point of comparison for a collection like the HM", "To emphasize the ubiquity of hand-copied collections like the FA and the HM in medieval England", "To illustrate how the discussion of the HM earlier in the text can improve historians’ understanding of the FA"], "correctAnswer": 0}, {"id": "re2-q7", "passage": "Vertical gene transfer involves the transmission of genetic material from a parent to offspring; horizontal gene transfer, on the other hand, involves the exchange of genetic material between organisms not in a parent-offspring relationship. {{u}}While horizontal gene transfer is common among prokaryotes—single-celled organisms, such as the bacteria Brevibacillus borstelensis and Lactobacillus curvatus—it has rarely been observed among eukaryotes (multicellular organisms).{{/u}} However, new studies suggest that horizontal gene transfer is more common in eukaryotes than originally thought.", "questionText": "Which choice best states the function of the underlined sentence in the text as a whole?", "difficulty": null, "skill": "Text Structure and Purpose", "tags": [], "type": "mcq", "choices": ["It argues that two biological phenomena are more similar than they may initially appear to be.", "It contrasts the frequency with which a biological phenomenon has been detected in two categories of organisms.", "It explains why a common perception of a biological process is flawed.", "It indicates a distinction between the mechanics of two kinds of biological processes."], "correctAnswer": 1}, {"id": "re2-q8", "passage": "Text 1 is T.L. Hulme’s 1912 poem \"Above the Dock.\"{{br}}{{br}}Text 2 is from Amy Lowell’s 1912 poem \"The Crescent Moon.\"{{br}}{{quote}}Text 1{{br}}{{br}}Above the quiet dock in mid night,{{br}}{{br}}Tangled in the tall mast’s corded height,{{br}}{{br}}Hangs the moon. What seemed so far away{{br}}{{br}}Is but a child’s balloon, forgotten after play.{{br}}{{br}}Text 2{{br}}{{br}}Slipping softly through the sky{{br}}{{br}}Little horned, happy moon,{{br}}{{br}}Can you hear me up so high?{{br}}{{br}}Will you come down soon?{{/quote}}", "questionText": "Which choice best describes a notable difference in how the speaker of Text 1 and the speaker of Text 2 portray the moon?", "difficulty": null, "skill": "Cross-Text Connections", "tags": [], "type": "mcq", "choices": ["While both speakers characterize the moon as an entrapped figure, only the speaker of Text 2 describes the moon as being content with this fate.", "While the speaker of Text 1 presents the moon as an object of play, the speaker of Text 2 presents the moon as an object of serious study.", "While the speaker of Text 1 presents the moon as seeming to be very close, the speaker of Text 2 emphasizes the moon’s distance from the speaker.", "While both speakers present the moon as a tangible object, only the speaker of Text 1 addresses the moon’s beauty."], "correctAnswer": 2}, {"id": "re2-q9", "passage": "Biologist Abbigail Merrill and colleagues conducted a study of how butterfly color and weather conditions relate to butterfly behavior, which wouldn’t have been possible without data gathered by students and other amateur science enthusiasts in the community. Considering over three years’ worth of data, the researchers found that orange butterflies were observed in the evening more often than any other butterflies, and that butterflies tended to prefer orange and red flowers on cloudy days and multicolor flowers on partly cloudy days.", "questionText": "According to the text, which factors seemed to be linked to the behavior of butterflies in Abbigail Merrill and colleagues’ study?", "difficulty": null, "skill": "Central Ideas and Details", "tags": [], "type": "mcq", "choices": ["Butterfly color but not weather conditions", "Weather conditions but not butterfly color", "Neither butterfly color nor weather conditions", "Both butterfly color and weather conditions"], "correctAnswer": 3}, {"id": "re2-q10", "passage": "Mauricio Drelichman and Hans-Joachim Voth’s research into the debt defaults of Philip II (who ruled an empire including Spain and Sicily from 1556 to 1598) relates to other work on European early modern state finance, including Hoffman and Norberg’s research on the relationship between state finance and political development. But Drelichman and Voth’s unique contribution to the field is their reconstruction of the earliest extant set of annual fiscal records for any sovereign state, demonstrating in turn that Philip’s defaults were caused by short-term cash shortages, not long-term unsustainable debts.", "questionText": "Which choice best states the main idea of the text?", "difficulty": null, "skill": "Central Ideas and Details", "tags": [], "type": "mcq", "choices": ["The research by Drelichman and Voth suggests that the logistics of ruling both Spain and Sicily led to short-term problems with cash that forced Philip II to default on his debts.", "Drelichman and Voth advanced the field of research on European early modern state finance by assembling a novel collection of evidence that gave them insight into Philip II’s debt defaults.", "Analysis of the earliest available records of a sovereign state’s finances can be found not in the work of Hoffman and Norberg but in that of Drelichman and Voth.", "Drelichman and Voth’s research on Philip II’s debt defaults builds on earlier work by Hoffman and Norberg, adding nuance to the earlier work’s findings."], "correctAnswer": 1}, {"id": "re2-q11", "passage": "The following text is adapted from William Shakespeare’s 1597 play {{i}}The Tragedy of King Richard III{{/i}}. Richard is reflecting on the recent arrest of his brother, the Duke of Clarence, on suspicion of treason against King Edward IV. Derby, Hastings, Buckingham, Rivers, Dorset, and Grey are also members of the English nobility.{{br}}{{br}}{{quote}}RICHARD: I do the wrong, and first begin to brawl.{{br}}{{br}}The secret mischiefs that I set [flowing]{{br}}{{br}}I lay unto the grievous charge of others.{{br}}{{br}}Clarence, whom I indeed have cast in darkness,{{br}}{{br}}I do beweep to many simple [gullible people],{{br}}{{br}}Namely, to Derby, Hastings, Buckingham;{{br}}{{br}}And tell them 'tis the Queen and her allies{{br}}{{br}}That stir the King against the Duke my brother.{{br}}{{br}}Now they believe it, and withal whet me{{br}}{{br}}To be revenged on Rivers, Dorset, Grey.{{/quote}}", "questionText": "Which choice best describes what happens in the text?", "difficulty": null, "skill": "Central Ideas and Details", "tags": [], "type": "mcq", "choices": ["Richard attributes Clarence’s troubles to both his own secret plotting and the distrust of Clarence that the queen and her allies Derby, Hastings, and Buckingham have planted in the king’s mind.", "Richard describes having wept as he informed Derby, Hastings, and Buckingham that the queen and her allies convinced the king to act against Clarence, and says that the earnestness of his grief caused them to accept his version of events.", "Richard indicates that he has pretended to be aggrieved about Clarence’s situation and has proclaimed it to be the fault of the queen and her allies, but in reality, he has caused the hostility the king feels toward Clarence.", "Richard acknowledges that his mischievous nature has spurred him to commit misdeeds in the past, including instigating enmity between the king and Clarence, but he reports that he has hitherto not lost the trust of the queen and her allies."], "correctAnswer": 2}, {"id": "re2-q12", "passage": "In what is now southern Florida, the Calusa people (circa 1000-1600 CE) supported their relatively large population’s dietary needs with hydrological engineering rather than terrestrial farming methods. They constructed watercourts (gated coastal enclosures) out of shells and sediments to trap a variety of fish as waters rose and fell with tides and seasonal sea-level shifts; watercourt pools then held the fish for later consumption. Archaeologist Theresa Schober has posited an additional purpose of these enclosures, suggesting that they were intended to foster conch. She ties this hypothesis to the high value the sea snails would have had for the Calusa, both nutritionally and as a building material (conch shells are highly durable).", "questionText": "Which finding, if true, would most directly weaken Schober’s hypothesis?", "difficulty": null, "skill": "Command of Evidence (Textual)", "tags": [], "type": "mcq", "choices": ["Samples of animal remains collected at Calusa sites reflect a greater diversity of marine species, particularly among sea snails, within the perimeter of watercourts than in locations known to have been devoted to the preparation and consumption of food.", "Radar surveys of Calusa sites reveal watercourt dimensions suitable for sustaining fish of many local species but not conducive for maintaining the shallow environments with ample seagrasses that allow sea snails to thrive.", "Sediment layers excavated from Calusa watercourt sites contain heterogeneous mixtures of scales from multiple species of fish and fragments of shells from various types of sea snails, but conch shells do not constitute the majority of the mixture in most of those layers.", "Historical population-size estimates suggest that the sea snails and fish most common in the Calusa diet were plentiful in open coastal waters when the watercourts were constructed but decreased in abundance in the years immediately after construction."], "correctAnswer": 1}, {"id": "re2-q13", "passage": "Observed Traits in a Population of Broadleaf Arrowhead, by Flowering Date{{br}}{{table}}Day|5|10|15|20{{row}}Total open male and female flowers per growth unit|25|65|110|45{{row}}Estimated reproductive success rate of male flowers|0.29|0.29|0.29|0.29{{row}}Proportion of male flowers|0.45|0.50|0.48|0.13{{/table}}{{br}}{{br}}The mating environment hypothesis predicts that populations of flowering plants compensate for reduced mating opportunities due to dichogamy (a plant’s expression of male and female functions at separate times to prevent self-pollination) by adjusting the bias of floral sex allocation during the flowering period, increasing the probability of successful cross-plant pollination. Researchers tested the hypothesis by examining a population of broadleaf arrowhead, a plant for which bloom onset generally takes longer for male flowers than for female flowers, during the flowering season. They concluded that the mating environment hypothesis is not well supported by their observational data.", "questionText": "Which choice best describes data from the table that support the researchers’ conclusion?", "difficulty": null, "skill": "Command of Evidence (Quantitative)", "tags": [], "type": "mcq", "choices": ["Whereas the total number of open flowers per growth unit peaked on day 15, the proportion of male flowers experienced a peak earlier in the flowering season, on day 10.", "Despite the sharp reduction in the total number of open flowers per growth unit from day 15 to 20, there was no decline in the estimated reproductive success rate of male flowers in that interval.", "Although sex allocations became overwhelmingly female biased by day 20, male flowers’ estimated reproductive success rate did not vary from day 5 to 20.", "Sex allocations were largely evenly distributed on days 10 and 15 but were female biased on days 5 and 20."], "correctAnswer": 2}, {"id": "re2-q14", "passage": "Although Grant Tavinor concludes that computer games are art by virtue of their forming a subcategory of fiction, and Berys Gaut similarly places them within the realm of cinema, neither approach adequately captures a central aspect of playing these games: when the player no longer attends to the narrative and is instead simply absorbed in the instrumentalities of gameplay. This is among the reasons philosopher C. Thi Nguyen contends that the work of computer-game designers is in what he calls the medium of player agency, which the designer prescribes through rules and goals, and which elicits positive aesthetic experiences in the player who agrees to adopt it. Therefore, Nguyen’s position is that Tavinor’s and Gaut’s frameworks ______", "questionText": "Which choice most logically completes the text?", "difficulty": null, "skill": "Inferences", "tags": [], "type": "mcq", "choices": ["subsume computer games under other categories of media that do not address a feature of games that is integral to player enjoyment.", "overstate the influence of fiction and cinema on the narrative elements of computer games.", "are helpful starting points for studying computer games as art, even though these frameworks are overly simplistic.", "are useful for analyzing the narrative aspects of computer games, even if neither attempts to address player agency."], "correctAnswer": 0}, {"id": "re2-q15", "passage": "As observed in a 1990 study by Kristina Sundbäck and colleagues, macroalgal proliferation may have a suppressive effect on the abundance of chlorophytes and other microphytobenthos (MPB)—chlorophyll-producing microbes inhabiting marine sediment—in part by reducing the amount of sunlight available to MPB. Examining benthic chlorophyll concentrations (a widely used proxy for MPB biomass) in mudflats in Hummock Cove and other coastal sites in Virginia, Alice F. Besterman and Michael L. Pace found that those concentrations did not negatively correlate with macroalgal proliferation. However, they noted that MPB may respond to low-light conditions by producing higher-than-normal concentrations of chlorophyll, and they thus concluded that ______", "questionText": "Which choice most logically completes the text?", "difficulty": null, "skill": "Inferences", "tags": [], "type": "mcq", "choices": ["researchers ought to account for the possibility that because MPB have the capacity to compensate for reduced sunlight availability, benthic chlorophyll concentrations may not always be a reliable indicator of MPB biomass.", "although elevated levels of macroalgae do not always correspond to increased levels of benthic chlorophyll, there is likely a larger trend in MPB biomass that is related to macroalgal presence but unrelated to light conditions.", "the effect of macroalgal concentrations on MPB abundance that Sundbäck and colleagues reported was not observed in Hummock Cove and other Virginia sites because low-light conditions likely are not generalizable across the sites in the studies.", "although their finding was inconsistent with that of Sundbäck and colleagues, this discrepancy was not attributable to the ability of MPB to accelerate chlorophyll production to mitigate the negative impact of macroalgal accumulations."], "correctAnswer": 0}, {"id": "re2-q16", "passage": "Neuroscientist Artin Arshamian and his team sought to determine what affects a person’s perception of an odor as pleasant: is it culture, personal taste, or aspects of human anatomy? The team assessed odor preferences in ten groups of people with different modes of living (urban, agricultural, and hunter-gatherer) including the Semaq Beri people from a small community in the Malay Peninsula and the Imbabura Quichua people from a small community in Ecuador. The team observed that across cultures, people generally rated odors about the same: phenethyl alcohol, which smells like roses, was typically rated more pleasant than mushroom alcohol, which smells like fungus. The team’s study thus undermined the idea that ______", "questionText": "Which choice most logically completes the text?", "difficulty": null, "skill": "Inferences", "tags": [], "type": "mcq", "choices": ["a person who perceives certain odors as pleasant will likely perceive the odors as roughly equal in pleasantness.", "culture significantly influences whether a person perceives an odor as pleasant or unpleasant.", "people agree in their perception of odors as pleasant or unpleasant regardless of where they live.", "personal taste has little influence on whether odors are perceived as pleasant or unpleasant."], "correctAnswer": 1}, {"id": "re2-q17", "passage": "Branching in Jurisprudential Schools is one of the hundreds of thousands of manuscripts that have survived from roughly the sixteenth century to the present ______ being passed down through private libraries in the city of Timbuktu, Mali. Many of these manuscripts can be found at the Ahmad Boularaf Library.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Boundaries", "tags": [], "type": "mcq", "choices": ["day by", "day by,", "day. By", "day; by"], "correctAnswer": 0}, {"id": "re2-q18", "passage": "The terms included in Barry Lopez and Debra Gwartney’s {{i}}Home Ground: A Guide to the American{{/i}} ______ such as \"erg,\" which refers to a large area covered by a sea of windswept sand dunes—illustrate the rich vocabulary used to describe the landforms of North America.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Boundaries", "tags": [], "type": "mcq", "choices": ["{{i}}Landscape{{/i}}", "{{i}}Landscape{{/i}}—", "{{i}}Landscape{{/i}}:", "{{i}}Landscape{{/i}},"], "correctAnswer": 1}, {"id": "re2-q19", "passage": "Following the formation of the European Union (EU) that same year, the organizers of the 1992 Tour de France wanted the bike race to reflect the cross-national flow of people and trade that the EU had made possible. The resulting course was 2,500 miles long _____ seven separate borders of neighboring countries, modeled a vision of the EU’s unifying aims.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Form, Structure, and Sense", "tags": [], "type": "mcq", "choices": ["and, crossing", "and crossed", "and, crossed", "and had crossed"], "correctAnswer": 0}, {"id": "re2-q20", "passage": "As part of his Today series, Japanese conceptual artist On Kawara spent nearly fifty years—with near daily consistency—writing the date in simple white strokes on a monochrome background, resulting in pieces such as 2 JAN. 1971. Such meticulous documentation of mundane ______ artworks that \"resonate with existential, psychological and scientific implications about the time-space continuum,\" according to the New York Times, became Kawara’s life’s work.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Form, Structure, and Sense", "tags": [], "type": "mcq", "choices": ["information, has generated", "information, generating", "information generated", "information generates"], "correctAnswer": 1}, {"id": "re2-q21", "passage": "For her film {{i}}I Am Somebody{{/i}} (1970), a documentary about a successful months-long strike held by Black female hospital workers in Charleston, South Carolina, director Madeline Anderson chose a narrator who had participated in the ______ by allowing the narrative to be shaped by one of their own, amplified the agency and power the workers possessed.", "questionText": "Which choice completes the text so that it conforms to the conventions of Standard English?", "difficulty": null, "skill": "Boundaries", "tags": [], "type": "mcq", "choices": ["protest; a decision that,", "protest a decision that,", "protest. A decision that", "protest, a decision that,"], "correctAnswer": 3}, {"id": "re2-q22", "passage": "At a time when many women writers used male pseudonyms to gain greater freedom of self-expression by evading gender conventions, Katherine Bradley and Edith Cooper adapted the practice by publishing poetry, prose, and drama for four decades under the shared name Michael Field. ______ the duo was able to express the joint creative vision that sustained their long personal and professional partnership.", "questionText": "Which choice completes the text with the most logical transition?", "difficulty": null, "skill": "Transitions", "tags": [], "type": "mcq", "choices": ["In this way,", "On the other hand,", "For instance,", "Later,"], "correctAnswer": 0}, {"id": "re2-q23", "passage": "In a 1997 study by Mofareh et al., the researchers’ aim was to analyze the diet composition of cattle in New Mexico. ______ they aimed to analyze the ratio of three different plant subtypes within these animals’ diet: graminoids, forbs, and browse.", "questionText": "Which choice completes the text with the most logical transition?", "difficulty": null, "skill": "Transitions", "tags": [], "type": "mcq", "choices": ["Specifically,", "Instead,", "All the same,", "Therefore,"], "correctAnswer": 0}, {"id": "re2-q24", "passage": "DeWitt Clinton employed the pseudonym \"Atticus\"—a reference to an ancient Roman figure—in political essays he wrote in 1795, a choice that accomplished far more than simply concealing his authorship. ______ it wasn’t an arbitrary pen name but rather a complex rhetorical strategy through which Clinton aligned his political views with the venerated republican ideals of the ancient world, thereby bolstering the authority of his writing.", "questionText": "Which choice completes the text with the most logical transition?", "difficulty": null, "skill": "Transitions", "tags": [], "type": "mcq", "choices": ["Indeed,", "However,", "In addition,", "Conversely,"], "correctAnswer": 0}, {"id": "re2-q25", "passage": "While researching a topic, a student has taken the following notes:{{bullets}}Brussels sprouts are vegetables that contain ascorbic acid, an essential nutrient for humans.{{item}}Grapes are fruits that contain ascorbic acid.{{item}}There is 80 milligrams (mg) of ascorbic acid per every 100 grams (g) of brussels sprouts.{{item}}There is 10 mg of ascorbic acid per every 100 g of grapes.{{item}}Humans cannot make ascorbic acid in their bodies, so they must get it from foods, including fruits and vegetables.{{item}}Ascorbic acid is also known as vitamin C.{{/bullets}}", "questionText": "The student wants to refute a claim that grapes are a better source of vitamin C than brussels sprouts are. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "difficulty": null, "skill": "Rhetorical Synthesis", "tags": [], "type": "mcq", "choices": ["Humans cannot make ascorbic acid in their bodies, but they can get it from brussels sprouts and grapes.", "Brussels sprouts contain vitamin C (also known as ascorbic acid); in fact, there is 80 mg of vitamin C in every 100 g of brussels sprouts.", "Brussels sprouts contain ascorbic acid (also known as vitamin C), and grapes do too.", "With 80 mg of vitamin C per every 100 g, brussels sprouts are actually a better source of vitamin C than grapes, which contain only 10 mg per every 100 g."], "correctAnswer": 3}, {"id": "re2-q26", "passage": "{{bullets}}Snow hydrologist Julie Koeberle helps maintain automated snow measurement stations.{{item}}They are called SNOTEL sites.{{item}}There are around 90 stations throughout Wyoming.{{item}}One is at Castle Creek.{{item}}The data collected can help researchers make downstream water supply predictions.{{/bullets}}", "questionText": "Which choice most effectively uses information from the given sentences to provide an example of a SNOTEL site?", "difficulty": null, "skill": "Rhetorical Synthesis", "tags": [], "type": "mcq", "choices": ["Snow hydrologist Julie Koeberle helps maintain automated snow monitoring stations known as SNOTEL sites.", "The SNOTEL site at Castle Creek is one of around 90 automated snow measurement stations in Wyoming.", "The data collected by SNOTEL sites can help researchers predict downstream water supplies.", "Located throughout Wyoming, SNOTEL sites monitor snow conditions."], "correctAnswer": 1}, {"id": "re2-q27", "passage": "While researching a topic, a student has taken the following notes:{{bullets}}The nautical mile (6,076 feet) is the measure of distance used in seafaring navigation.{{item}}A nautical mile directly correlates to one minute (1/60th of a degree) of latitude.{{item}}The curvature of Earth affects the accurate measurement of long distances when using flat maps.{{item}}Measuring distances with latitude and longitude coordinates takes into account Earth’s curvature.{{item}}Mariners use nautical charts marked with latitude and longitude to quickly calculate distances and positions.{{/bullets}}", "questionText": "The student wants to explain why nautical miles are used to measure distances in seafaring navigation. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "difficulty": null, "skill": "Rhetorical Synthesis", "tags": [], "type": "mcq", "choices": ["Using nautical miles for navigation at sea takes Earth’s curvature into account, whereas measuring distances with latitude and longitude coordinates does not.", "Nautical charts use latitude and longitude to measure long distances; these charts are more accurate than flat maps for measuring distances in seafaring navigation because they account for Earth’s curvature.", "Since they directly correlate to the coordinates on nautical charts, which take into account Earth’s curvature, nautical miles are an efficient way to calculate distances at sea.", "Nautical miles are a measure of distance equal to one minute of latitude, which is a feature nautical charts use to calculate distances and positions."], "correctAnswer": 2}]}, {"moduleId": "2025-august-asia-v1-math1", "section": "Math", "moduleLabel": "Module 1", "timeLimitMinutes": 35, "questions": [{"id": "ma1-q1", "passage": null, "questionText": "The length of each side of triangle A is 270 millimeters. The length of each side of triangle B is double the length of each side of triangle A. What is the length, in millimeters, of each side of triangle B?", "difficulty": null, "skill": "Lines, angles, and triangles", "tags": [], "type": "mcq", "choices": ["270", "272", "540", "1,080"], "correctAnswer": 2}, {"id": "ma1-q2", "passage": null, "questionText": "Carrie has {{m}}c{{/m}} dollars and Marjani has {{m}}m{{/m}} dollars. Carrie has 4 times as many dollars as Marjani, and together they have a total of $40.00. Which system of equations represents this situation?", "difficulty": null, "skill": "Systems of two linear equations in two variables", "tags": [], "type": "mcq", "choices": ["{{m}}c = 4m{{/m}}{{br}}{{m}}c + m = 40{{/m}}", "{{m}}m = 4c{{/m}}{{br}}{{m}}c + m = 40{{/m}}", "{{m}}c = 40m{{/m}}{{br}}{{m}}c + m = 4{{/m}}", "{{m}}m = 40c{{/m}}{{br}}{{m}}c + m = 4{{/m}}"], "correctAnswer": 0}, {"id": "ma1-q3", "passage": null, "questionText": "Anton is selling toys from his toy collection. When he started selling the toys, there were 2,800 toys in the collection. At the end of each week for 3 weeks after Anton started selling the toys, the number of toys in the collection had decreased by {{m}}\\frac{1}{2}{{/m}} of the toys in the collection at the end of the previous week. Which equation gives the number of toys, {{m}}c{{/m}}, in the collection {{m}}w{{/m}} weeks after Anton started selling the toys, where {{m}}0 \\le w \\le 3{{/m}}?", "difficulty": null, "skill": "Nonlinear functions", "tags": [], "type": "mcq", "choices": ["{{m}}c = w^{\\frac{1}{2}}{{/m}}", "{{m}}c = 2{,}800^{w}{{/m}}", "{{m}}c = 1{,}400\\left(\\frac{1}{2}\\right)^{w}{{/m}}", "{{m}}c = 2{,}800\\left(\\frac{1}{2}\\right)^{w}{{/m}}"], "correctAnswer": 3}, {"id": "ma1-q4", "passage": "{{mm}}\\sqrt{w} + 22 = 28{{/mm}}", "questionText": "What is the solution to the given equation?", "difficulty": null, "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": [], "type": "mcq", "choices": ["2", "3", "12", "36"], "correctAnswer": 3}, {"id": "ma1-q5", "passage": null, "questionText": "The function f is defined by {{m}}f(x) = 7x^{3} + 6{{/m}}. What is the value of {{m}}f(2){{/m}}?", "difficulty": null, "skill": "Nonlinear functions", "tags": [], "type": "spr", "correctAnswer": "62"}, {"id": "ma1-q6", "passage": null, "questionText": "The function {{m}}f(x) = -30x + 310{{/m}} gives the predicted height above the ground {{m}}f(x){{/m}}, in feet, of a model airplane {{m}}x{{/m}} minutes after it begins to descend. What is the predicted height above the ground, in feet, of the model airplane 2 minutes after it begins to descend?", "difficulty": null, "skill": "Linear functions", "tags": [], "type": "mcq", "choices": ["60", "250", "280", "370"], "correctAnswer": 1}, {"id": "ma1-q7", "passage": null, "questionText": "{{mm}}2x = 9 + 7y{{/mm}}{{mm}}-2x = 3 + 7y{{/mm}}The solution to the given system of equations is (x, y). What is the value of 4x?", "difficulty": null, "skill": "Systems of two linear equations in two variables", "tags": [], "type": "spr", "correctAnswer": "6"}, {"id": "ma1-q8", "passage": null, "questionText": "A bank account was opened with an initial deposit. Over the next several months, regular deposits were made into this account, and there were no withdrawals made during this time. The graph of the function f shown, where {{m}}y = f(x){{/m}}, estimates the account balance, in dollars, in this bank account {{m}}x{{/m}} months since the initial deposit. To the nearest whole dollar, what is the amount of the initial deposit estimated by the graph?", "difficulty": null, "skill": "Linear functions", "tags": [], "type": "spr", "correctAnswer": "15", "figure": "data:image/png;base64,"}, {"id": "ma1-q9", "passage": null, "questionText": "{{mm}}y = -12x + 16{{/mm}}{{mm}}y = -20x + 24{{/mm}}What is the solution (x, y) to the given system of equations?", "difficulty": null, "skill": "Systems of two linear equations in two variables", "tags": [], "type": "mcq", "choices": ["(1,4)", "(16,24)", "(24, 16)", "(4,1)"], "correctAnswer": 0}, {"id": "ma1-q10", "passage": null, "questionText": "A rectangle has a length that is 73 times its width. The function {{m}}y = (73w)(w){{/m}} represents this situation, where {{m}}y{{/m}} is the area, in square feet, of the rectangle and {{m}}y > 0{{/m}}. Which of the following is the best interpretation of {{m}}73w{{/m}} in this context?", "difficulty": null, "skill": "Nonlinear functions", "tags": [], "type": "mcq", "choices": ["The length of the rectangle, in feet", "The area of the rectangle, in square feet", "The difference between the length and the width of the rectangle, in feet", "The width of the rectangle, in feet"], "correctAnswer": 0}, {"id": "ma1-q11", "passage": null, "questionText": "An entomologist placed an initial population of 40 Tenebrio molitor, a type of beetle, into a habitat and monitored the population over time. When the number of Tenebrio molitor in the habitat reached 170% of the initial population, the entomologist moved 75% of the Tenebrio molitor to a second habitat. How many Tenebrio molitor did the entomologist move to the second habitat at this time?", "difficulty": null, "skill": "Percentages", "tags": [], "type": "spr", "correctAnswer": "51"}, {"id": "ma1-q12", "passage": null, "questionText": "For the polynomial function {{m}}f{{/m}}, the graph of {{m}}y = f(x){{/m}} in the {{m}}xy{{/m}}-plane passes through the points {{m}}(-3, 0){{/m}}, {{m}}(1, 0){{/m}}, and {{m}}(4, 0){{/m}}. Which of the following must be a factor of {{m}}f(x){{/m}}?", "difficulty": null, "skill": "Nonlinear functions", "tags": [], "type": "mcq", "choices": ["{{m}}x+1{{/m}}", "{{m}}x+4{{/m}}", "{{m}}x-1{{/m}}", "{{m}}x-3{{/m}}"], "correctAnswer": 2}, {"id": "ma1-q13", "passage": null, "questionText": "A circle has a circumference of 89π centimeters. What is the diameter, in centimeters, of the circle?", "difficulty": null, "skill": "Circles", "tags": [], "type": "spr", "correctAnswer": "89"}, {"id": "ma1-q14", "passage": null, "questionText": "If {{m}}\\frac{x-17}{18} = \\frac{x-17}{6}{{/m}}, what is the value of {{m}}x + 17{{/m}}?", "difficulty": null, "skill": "Linear equations in one variable", "tags": [], "type": "mcq", "choices": ["0", "3", "17", "34"], "correctAnswer": 3}, {"id": "ma1-q15", "passage": null, "questionText": "For what value of {{m}}a{{/m}} is {{m}}\\sqrt[a]{r^{42}}{{/m}} equivalent to {{m}}r^{\\frac{6}{7}}{{/m}}, where {{m}}r > 1{{/m}}?", "difficulty": null, "skill": "Equivalent expressions", "tags": [], "type": "spr", "correctAnswer": "49"}, {"id": "ma1-q16", "passage": null, "questionText": "In the {{m}}xy{{/m}}-plane, line {{m}}s{{/m}} passes through the point {{m}}(0, 0){{/m}} and is parallel to the line represented by the equation {{m}}y = 36x + 6{{/m}}. If line {{m}}s{{/m}} also passes through the point {{m}}(9, d){{/m}}, what is the value of {{m}}d{{/m}}?", "difficulty": null, "skill": "Linear equations in two variables", "tags": [], "type": "spr", "correctAnswer": "324"}, {"id": "ma1-q17", "passage": null, "questionText": "Circles A and B are graphed in the xy-plane. Circle A is represented by the equation {{m}}(x + 8)^{2} + (y - 8)^{2} = 64{{/m}} and intersects the x-axis at the point {{m}}(r, s){{/m}}. Circle B has its center at {{m}}(r, s){{/m}} and has a radius of the same length as circle A. Which equation represents circle B?", "difficulty": null, "skill": "Circles", "tags": [], "type": "mcq", "choices": ["{{m}}x^{2} + (y + 8)^{2} = 64{{/m}}", "{{m}}x^{2} + (y - 8)^{2} = 64{{/m}}", "{{m}}(x + 8)^{2} + y^{2} = 64{{/m}}", "{{m}}(x - 8)^{2} + y^{2} = 64{{/m}}"], "correctAnswer": 2}, {"id": "ma1-q18", "passage": "The dot plots represent the distributions of values in data sets A and B.", "questionText": "Which of the following statements must be true?{{br}}{{quote}}I. The median of data set A is equal to the median of data set B.{{br}}II. The standard deviation of data set A is equal to the standard deviation of data set B.{{/quote}}", "difficulty": null, "skill": "One-variable data: Distributions and measures of center and spread", "tags": [], "type": "mcq", "choices": ["I and II", "I only", "II only", "Neither I nor II"], "correctAnswer": 1, "figure": "data:image/png;base64,"}, {"id": "ma1-q19", "passage": "The scatterplot shows the relationship between two variables, {{m}}x{{/m}} and {{m}}y{{/m}}. A line of best fit for the data is also shown.", "questionText": "For how many of the 9 data points is the actual {{m}}y{{/m}}-value greater than the {{m}}y{{/m}}-value predicted by the line of best fit?", "difficulty": null, "skill": "Two-variable data: Models and scatterplots", "tags": [], "type": "mcq", "choices": ["8", "7", "5", "2"], "correctAnswer": 2, "figure": "data:image/png;base64,"}, {"id": "ma1-q20", "passage": null, "questionText": "{{mm}}RS = 504{{/mm}}{{mm}}ST = 128{{/mm}}{{mm}}TR = 520{{/mm}}The side lengths of right triangle {{m}}RST{{/m}} are given. Triangle {{m}}RST{{/m}} is similar to triangle {{m}}UVW{{/m}}, where {{m}}S{{/m}} corresponds to {{m}}V{{/m}} and {{m}}T{{/m}} corresponds to {{m}}W{{/m}}. What is the value of {{m}}\\tan W{{/m}}?", "difficulty": null, "skill": "Right triangles and trigonometry", "tags": [], "type": "mcq", "choices": ["{{m}}\\frac{16}{65}{{/m}}", "{{m}}\\frac{16}{63}{{/m}}", "{{m}}\\frac{63}{65}{{/m}}", "{{m}}\\frac{63}{16}{{/m}}"], "correctAnswer": 3}, {"id": "ma1-q21", "passage": "{{mm}}f(x) = 20(2)^{x} + 6(2)^{x}{{/mm}}", "questionText": "The function f is defined by the given equation. Which of the following equivalent forms of {{m}}f{{/m}} displays, as a coefficient or a base, the {{m}}y{{/m}}-coordinate of the {{m}}y{{/m}}-intercept of the graph of {{m}}y = f(x){{/m}} in the {{m}}xy{{/m}}-plane?", "difficulty": null, "skill": null, "tags": [], "type": "mcq", "choices": ["{{m}}f(x) = 80(2)^{x-2} + 24(2)^{x-2}{{/m}}", "{{m}}f(x) = 2\\left(10(2)^{x} + 3(2)^{x}\\right){{/m}}", "{{m}}f(x) = 20(4)^{\\frac{x}{2}} + 6(4)^{\\frac{x}{2}}{{/m}}", "{{m}}f(x) = 26(2)^{x}{{/m}}"], "correctAnswer": 3}, {"id": "ma1-q22", "passage": null, "questionText": "In a set of three consecutive integers, where the integers are ordered from least to greatest, the first integer is represented by {{m}}x{{/m}}. The sum of 4 and the second integer is less than the product of 17 and the third integer. Which inequality represents this situation?", "difficulty": null, "skill": "Linear inequalities in one or two variables", "tags": [], "type": "mcq", "choices": ["{{m}}4 + (x+1) > 17(x+2){{/m}}", "{{m}}4 + (x+1) < 17(x+2){{/m}}", "{{m}}4 + (x+2) > 17(x+3){{/m}}", "{{m}}4 + (x+2) < 17(x+3){{/m}}"], "correctAnswer": 1}]}, {"moduleId": "2025-august-asia-v1-math2", "section": "Math", "moduleLabel": "Module 2", "timeLimitMinutes": 35, "questions": [{"id": "ma2-q1", "passage": null, "questionText": "The function {{m}}g{{/m}} is defined by {{m}}g(x) = 19 - x{{/m}}. What is the value of {{m}}g(4){{/m}}?", "difficulty": null, "skill": "Linear functions", "tags": [], "type": "mcq", "choices": ["4", "15", "19", "23"], "correctAnswer": 1}, {"id": "ma2-q2", "passage": null, "questionText": "Micah deposited a total of $6,600 into two retirement accounts last year by depositing {{m}}x{{/m}} dollars once each month into one account and {{m}}y{{/m}} dollars twice each month into the other account. Which equation represents this situation?", "difficulty": null, "skill": "Linear equations in two variables", "tags": [], "type": "mcq", "choices": ["{{m}}6{,}600 = 12x + 12y{{/m}}", "{{m}}6{,}600 = 12x + 24y{{/m}}", "{{m}}6{,}600 = 24x + 12y{{/m}}", "{{m}}6{,}600 = 24x + 24y{{/m}}"], "correctAnswer": 1}, {"id": "ma2-q3", "passage": null, "questionText": "The measure of angle {{m}}G{{/m}} is {{m}}\\frac{\\pi}{10}{{/m}} radians. If the measure of angle {{m}}G{{/m}} is {{m}}9n{{/m}} degrees, where {{m}}n{{/m}} is a constant, what is the value of {{m}}n{{/m}}?", "difficulty": null, "skill": "Circles", "tags": [], "type": "mcq", "choices": ["2", "9", "10", "18"], "correctAnswer": 0}, {"id": "ma2-q4", "passage": null, "questionText": "The ratio 6 to 3 is equivalent to the ratio 24 to {{m}}3k{{/m}}, where {{m}}k{{/m}} is a constant. What is the value of {{m}}k{{/m}}?", "difficulty": null, "skill": "Ratios, rates, proportional relationships, and units", "tags": [], "type": "mcq", "choices": ["0.75", "4", "12", "72"], "correctAnswer": 1}, {"id": "ma2-q5", "passage": null, "questionText": "Which expression is equivalent to {{m}}(8nr^{2} + 2nr) + (4n^{2}r + 3nr){{/m}}?", "difficulty": null, "skill": "Equivalent expressions", "tags": [], "type": "mcq", "choices": ["{{m}}12n^{2}r^{2} + 5nr{{/m}}", "{{m}}12n^{3}r^{3} + 5n^{2}r^{2}{{/m}}", "{{m}}32n^{3}r^{3} + 6n^{2}r^{2}{{/m}}", "{{m}}8nr^{2} + 4n^{2}r + 5nr{{/m}}"], "correctAnswer": 3}, {"id": "ma2-q6", "passage": "{{mm}}R = \\frac{0.43\\ell}{A}{{/mm}}", "questionText": "The given equation relates the resistance {{m}}R{{/m}}, in ohms, of a wire to its length {{m}}\\ell{{/m}}, in meters, and its cross-sectional area {{m}}A{{/m}}, in square meters. Which equation correctly expresses the length, in meters, of the wire in terms of its resistance, in ohms, and its cross-sectional area, in square meters?", "difficulty": null, "skill": "Equivalent expressions", "tags": [], "type": "mcq", "choices": ["{{m}}\\ell = \\frac{R-A}{0.43}{{/m}}", "{{m}}\\ell = \\frac{R+A}{0.43}{{/m}}", "{{m}}\\ell = \\frac{0.43R}{A}{{/m}}", "{{m}}\\ell = \\frac{AR}{0.43}{{/m}}"], "correctAnswer": 3}, {"id": "ma2-q7", "passage": null, "questionText": "The graphs of {{m}}y = -3x + 7{{/m}} and {{m}}y = x - 5{{/m}} are shown. Point {{m}}P{{/m}} (not shown) has coordinates {{m}}(3, -5){{/m}} and lies in the shaded region. The coordinates of {{m}}P{{/m}} satisfy which of the following inequalities?{{br}}{{quote}}I. {{m}}y < -3x + 7{{/m}}{{br}}II. {{m}}y > x - 5{{/m}}{{/quote}}", "difficulty": null, "skill": "Linear inequalities in one or two variables", "tags": [], "type": "mcq", "choices": ["I only", "II only", "I and II", "Neither I nor II"], "correctAnswer": 0, "figure": "data:image/png;base64,"}, {"id": "ma2-q8", "passage": "{{table}}{{m}}x{{/m}}|{{m}}y{{/m}}{{row}}0|{{m}}n{{/m}}{{row}}5|{{m}}n + 24{{/m}}{{row}}10|{{m}}n + 48{{/m}}{{/table}}", "questionText": "There is a linear relationship between {{m}}x{{/m}} and {{m}}y{{/m}}. The table shows three values of {{m}}x{{/m}} and their corresponding values of {{m}}y{{/m}} in terms of a constant {{m}}n{{/m}}. What is the slope of the line that represents this relationship in the xy-plane?", "difficulty": null, "skill": null, "tags": [], "type": "spr", "correctAnswer": "24/5", "altAnswers": ["4.8"]}, {"id": "ma2-q9", "passage": null, "questionText": "If {{m}}\\left(\\frac{1}{2}x - \\frac{21}{2}\\right)^{2} - 81 = 0{{/m}}, what is the value of {{m}}(x - 21)^{2}{{/m}}?", "difficulty": null, "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": [], "type": "mcq", "choices": ["324", "162", "21", "9"], "correctAnswer": 0}, {"id": "ma2-q10", "passage": null, "questionText": "Rectangles {{m}}ABCD{{/m}} and {{m}}EFGH{{/m}} are similar. The length of each side of {{m}}EFGH{{/m}} is 6 times the length of the corresponding side of {{m}}ABCD{{/m}}. The area of {{m}}ABCD{{/m}} is 90 square units. What is the area, in square units, of {{m}}EFGH{{/m}}?", "difficulty": null, "skill": "Area and volume", "tags": [], "type": "mcq", "choices": ["15", "36", "540", "3,240"], "correctAnswer": 3}, {"id": "ma2-q11", "passage": null, "questionText": "On a plot of land, 48.0% of the square footage is farmland and the remaining square footage is pasture. There are buildings on exactly 23.5% of the square footage of the farmland, and there are buildings on exactly 16.0% of the square footage of the pasture. If there are buildings on exactly {{m}}p{{/m}}% of the square footage of the plot of land, what is the value of {{m}}p{{/m}}?", "difficulty": null, "skill": "Percentages", "tags": [], "type": "spr", "correctAnswer": "19.6"}, {"id": "ma2-q12", "passage": "The scatterplot shows data set A, which consists of the weights {{m}}y{{/m}}, in pounds, of a Labrador retriever puppy at various ages, {{m}}x{{/m}}, in months. The equation of a line of best fit for the relationship in data set A can be written as {{m}}y = -5.1 + 8.7x{{/m}}, where {{m}}2 \\le x \\le 6{{/m}}.", "questionText": "The puppy was weighed again at 9 months old and weighed 52 pounds. Data set B consists of all the data points in data set A as well as the data point {{m}}(9, 52){{/m}}. The equation of a line of best fit for data set B can be written as {{m}}y = r + sx{{/m}}, where {{m}}r{{/m}} and {{m}}s{{/m}} are constants and {{m}}2 \\le x \\le 9{{/m}}. Assuming the equations of the lines of best fit are calculated in the same way, which of the following is the best estimate for the value of {{m}}s{{/m}}?", "difficulty": null, "skill": "Two-variable data: Models and scatterplots", "tags": [], "type": "mcq", "choices": ["5.9", "8.7", "13.8", "17.7"], "correctAnswer": 0, "figure": "data:image/png;base64,"}, {"id": "ma2-q13", "passage": null, "questionText": "If {{m}}|16 - 2x|{{/m}} {{m}}= 58{{/m}}, which of the following is a value of {{m}}8 - x{{/m}}?", "difficulty": null, "skill": "Linear equations in one variable", "tags": [], "type": "mcq", "choices": ["0", "8", "29", "42"], "correctAnswer": 2}, {"id": "ma2-q14", "passage": null, "questionText": "A book-of-the-month club charges $16 for the first book purchased during the month and an additional $11 for each book after the first. Which equation describes this situation, where {{m}}y{{/m}} is the total cost, in dollars, for books purchased during a month, {{m}}x{{/m}} is the number of books purchased during the month, and {{m}}x > 0{{/m}}?", "difficulty": null, "skill": "Linear functions", "tags": [], "type": "mcq", "choices": ["{{m}}y = x + 16{{/m}}", "{{m}}y = 11x + 16{{/m}}", "{{m}}y = 11(x-1) + 16{{/m}}", "{{m}}y = (x - 1) + 16{{/m}}"], "correctAnswer": 2}, {"id": "ma2-q15", "passage": null, "questionText": "A company developed a plan to set the selling price of a product. The company determined that for a selling price of $120.00, zero products would be sold. For each $2.50 decrease in the selling price, the number of products sold would increase by one. For a revenue of exactly $1,437.50, which of the following could be the number of products sold? (revenue = price × number of products sold)", "difficulty": null, "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": [], "type": "mcq", "choices": ["23", "24", "527", "1,440"], "correctAnswer": 0}, {"id": "ma2-q16", "passage": null, "questionText": "The equation of the graph shown is {{m}}y = a^{x} + b{{/m}}, where {{m}}a{{/m}} and {{m}}b{{/m}} are constants. What is the value of {{m}}a - b{{/m}}?", "difficulty": null, "skill": "Nonlinear functions", "tags": [], "type": "spr", "correctAnswer": "11", "figure": "data:image/png;base64,"}, {"id": "ma2-q17", "passage": "{{mm}}y = 7x^{2} - bx - 6{{/mm}}", "questionText": "Which of the following equations is equivalent to the given equation, where {{m}}b{{/m}} is a positive constant?", "difficulty": null, "skill": "Equivalent expressions", "tags": [], "type": "mcq", "choices": ["{{m}}y = 7\\left(x - \\frac{b}{14}\\right)^{2} - 6 - \\frac{b^{2}}{28}{{/m}}", "{{m}}y = 7\\left(x - \\frac{b}{14}\\right)^{2} - 6{{/m}}", "{{m}}y = 7\\left(x + \\frac{b}{14}\\right)^{2} - 6 - \\frac{b^{2}}{28}{{/m}}", "{{m}}y = 7\\left(x + \\frac{b}{14}\\right)^{2} - 6{{/m}}"], "correctAnswer": 0}, {"id": "ma2-q18", "passage": null, "questionText": "The equation {{m}}d = 6t + 210{{/m}} gives the distance {{m}}d{{/m}}, in feet, from a reference point on the surface of Mars to a Mars rover, where {{m}}t{{/m}} is the number of minutes after the start of a period of observation. By how many feet does the Mars rover’s distance from the reference point increase over a period of 20 minutes?", "difficulty": null, "skill": "Linear functions", "tags": [], "type": "mcq", "choices": ["330", "230", "120", "6"], "correctAnswer": 2}, {"id": "ma2-q19", "passage": null, "questionText": "A line intersects two parallel lines, forming four acute angles and four obtuse angles. The measure of one of the acute angles is {{m}}(7x - 410)^\\circ{{/m}}. The sum of the measures of one of the acute angles and three of the obtuse angles is {{m}}(-14x + w)^\\circ{{/m}}. What is the value of {{m}}w{{/m}}?", "difficulty": null, "skill": "Lines, angles, and triangles", "tags": [], "type": "spr", "correctAnswer": "1360"}, {"id": "ma2-q20", "passage": "The table summarizes the distribution of age and assigned group for 90 participants in a study.{{table}}|0–9 years|10–19 years|20+ years|Total{{row}}Group A|15|11|4|30{{row}}Group B|4|5|21|30{{row}}Group C|11|14|5|30{{row}}Total|30|30|30|90{{/table}}", "questionText": "One of these participants will be selected at random. What is the probability of selecting a participant from group A, given that the participant is at least 10 years of age?", "difficulty": null, "skill": "Probability and conditional probability", "tags": [], "type": "mcq", "choices": ["{{m}}\\frac{1}{6}{{/m}}", "{{m}}\\frac{1}{4}{{/m}}", "{{m}}\\frac{11}{30}{{/m}}", "{{m}}\\frac{1}{2}{{/m}}"], "correctAnswer": 1}, {"id": "ma2-q21", "passage": null, "questionText": "A circle in the {{m}}xy{{/m}}-plane has its center at {{m}}(2, 9){{/m}}. Line {{m}}t{{/m}} is tangent to this circle at the point {{m}}(a, -4){{/m}}, where {{m}}a{{/m}} is a constant. The slope of line {{m}}t{{/m}} is {{m}}\\frac{6}{5}{{/m}}. What is the value of {{m}}a{{/m}}?", "difficulty": null, "skill": "Circles", "tags": [], "type": "mcq", "choices": ["{{m}}-\\frac{68}{5}{{/m}}", "{{m}}-\\frac{53}{6}{{/m}}", "{{m}}\\frac{77}{6}{{/m}}", "{{m}}\\frac{88}{5}{{/m}}"], "correctAnswer": 3}, {"id": "ma2-q22", "passage": "{{mm}}-x^{2} + bx - 49 = 0{{/mm}}", "questionText": "In the given equation, {{m}}b{{/m}} is an integer. The equation has no real solutions. What is the least possible value of {{m}}b{{/m}}?", "difficulty": null, "skill": "Nonlinear equations in one variable and systems of equations in two variables", "tags": [], "type": "spr", "correctAnswer": "-13"}]}], "scoring": {"model": "per-module", "base": 200, "scoringSource": "estimated", "scoringNote": "David-supplied curve, linear administration", "rwM1": [0, 0, 20, 40, 60, 70, 80, 90, 100, 100, 110, 110, 120, 130, 140, 160, 170, 190, 210, 220, 240, 260, 270, 290, 310, 330, 340, 360], "rwM2": [0, 0, 0, 10, 10, 10, 20, 20, 20, 30, 30, 40, 50, 70, 90, 90, 100, 110, 130, 140, 150, 160, 180, 190, 200, 210, 230, 240], "mathM1": [0, 0, 20, 40, 60, 60, 80, 80, 100, 100, 110, 140, 160, 180, 200, 220, 240, 260, 290, 310, 330, 350, 370], "mathM2": [0, 0, 0, 20, 20, 30, 50, 70, 70, 70, 90, 90, 100, 100, 110, 130, 140, 160, 170, 190, 200, 220, 230]}, "testVersion": "2026-08-19-a", "legacyIds": []};
